// NBIS: branchless insertion sort.
// All comparisons compile to MINSD/MAXSD — no data-dependent branches,
// no mispredictions. O(n²) but dominates std::sort for n <= ~64 because
// the misprediction cost of introsort's partitioning exceeds NBIS's
// O(n²) branchless comparisons when everything fits in L1 cache.
template <typename T>
inline void nbis_sort(T* x, int n) {
  for (int i = 1; i < n; ++i) {
    T v = x[i];
    for (int j = i; j > 0; --j) {
      T lo = (std::min)(v, x[j - 1]);
      T hi = (std::max)(v, x[j - 1]);
      x[j - 1] = lo;
      x[j]     = hi;
      v = lo;
    }
  }
}

