// ============================================================
// Optimal median-selection networks (SorterHunter / Dobbelaere)
//
// Each function runs the minimum comparators needed to place the
// median correctly. Odd n: median at x[n/2]. Even n: both middle
// values at x[h-1],x[h] (any order); (x[h-1]+x[h])*0.5 is correct.
//
// Reference: https://github.com/bertdobbelaere/SorterHunter
// ============================================================

// n=3: 3 CEs, depth 3 (Median_3_3_3.json)
template <typename T>
inline T median_net_3(T* x) {
  SWAP_IF_GREATER(x[0],x[1]);
  SWAP_IF_GREATER(x[1],x[2]);
  SWAP_IF_GREATER(x[0],x[1]);
  return x[1];
}

// n=4: 4 CEs, depth 2 (Median_4_4_2.json)
template <typename T>
inline T median_net_4(T* x) {
  SWAP_IF_GREATER(x[0],x[1]);
  SWAP_IF_GREATER(x[2],x[3]);
  SWAP_IF_GREATER(x[0],x[2]);
  SWAP_IF_GREATER(x[1],x[3]);
  return (x[1]+x[2])*T(0.5);
}

